function parseQuery(qs) {
  if (qs === undefined || qs === null) return {};
  let s = String(qs);
  if (s.charAt(0) === '?') s = s.slice(1);
  if (s === '') return {};

  const result = {};

  const decode = (str) => {
    const replaced = str.replace(/\+/g, ' ');
    const bytes = [];
    const encoder = new TextEncoder();
    for (let i = 0; i < replaced.length; i++) {
      const ch = replaced[i];
      const code = ch.charCodeAt(0);
      if (ch === '%' && i + 2 < replaced.length) {
        const hex = replaced.slice(i + 1, i + 3);
        if (/^[0-9A-Fa-f]{2}$/.test(hex)) {
          bytes.push(parseInt(hex, 16));
          i += 2;
          continue;
        }
      }
      if (code < 128) {
        bytes.push(code);
      } else {
        const enc = encoder.encode(ch);
        for (let j = 0; j < enc.length; j++) bytes.push(enc[j]);
      }
    }
    try {
      return new TextDecoder('utf-8', { fatal: true }).decode(new Uint8Array(bytes));
    } catch (e) {
      return new TextDecoder('utf-8').decode(new Uint8Array(bytes));
    }
  };

  const setOwn = (obj, key, value) => {
    if (key === '__proto__') {
      Object.defineProperty(obj, key, {
        value,
        writable: true,
        enumerable: true,
        configurable: true
      });
    } else {
      obj[key] = value;
    }
  };

  const parts = s.split('&');
  for (let i = 0; i < parts.length; i++) {
    const part = parts[i];
    if (part === '') continue;
    const eq = part.indexOf('=');
    let rawKey, rawValue;
    if (eq === -1) {
      rawKey = part;
      rawValue = '';
    } else {
      rawKey = part.slice(0, eq);
      rawValue = part.slice(eq + 1);
    }
    const key = decode(rawKey);
    const value = decode(rawValue);
    if (Object.prototype.hasOwnProperty.call(result, key)) {
      const prev = result[key];
      const arr = Array.isArray(prev) ? prev : [prev];
      arr.push(value);
      setOwn(result, key, arr);
    } else {
      setOwn(result, key, value);
    }
  }
  return result;
}
