package main

import (
	"errors"
	"fmt"
	"regexp"
)

var canonicalRoman = regexp.MustCompile(`^M{0,3}(CM|CD|D?C{0,3})(XC|XL|L?X{0,3})(IX|IV|V?I{0,3})$`)

func RomanToInt(s string) (int, error) {
	if s == "" {
		return 0, errors.New("empty Roman numeral")
	}

	for i := 0; i < len(s); i++ {
		switch s[i] {
		case 'I', 'V', 'X', 'L', 'C', 'D', 'M':
		default:
			return 0, fmt.Errorf("invalid character %q", s[i])
		}
	}

	if !canonicalRoman.MatchString(s) {
		return 0, errors.New("non-canonical Roman numeral")
	}

	values := map[byte]int{
		'I': 1,
		'V': 5,
		'X': 10,
		'L': 50,
		'C': 100,
		'D': 500,
		'M': 1000,
	}

	total := 0
	for i := 0; i < len(s); i++ {
		value := values[s[i]]
		if i+1 < len(s) && values[s[i+1]] > value {
			total -= value
		} else {
			total += value
		}
	}

	return total, nil
}
