package main

import "sort"

func TopKWords(text string, k int) []string {
	if k <= 0 {
		return []string{}
	}

	counts := make(map[string]int)
	var word []byte

	flush := func() {
		if len(word) == 0 {
			return
		}
		counts[string(word)]++
		word = word[:0]
	}

	for i := 0; i < len(text); i++ {
		b := text[i]
		if (b >= 'a' && b <= 'z') || (b >= 'A' && b <= 'Z') {
			if b >= 'A' && b <= 'Z' {
				b += 'a' - 'A'
			}
			word = append(word, b)
		} else {
			flush()
		}
	}
	flush()

	type item struct {
		word string
		count int
	}

	items := make([]item, 0, len(counts))
	for w, c := range counts {
		items = append(items, item{w, c})
	}

	sort.Slice(items, func(i, j int) bool {
		if items[i].count != items[j].count {
			return items[i].count > items[j].count
		}
		return items[i].word < items[j].word
	})

	if k > len(items) {
		k = len(items)
	}

	result := make([]string, 0, k)
	for i := 0; i < k; i++ {
		result = append(result, items[i].word)
	}
	return result
}
