fn compress(s: &str) -> String {
    let mut out = String::new();
    let mut chars = s.chars();

    while let Some(c) = chars.next() {
        let mut len = 1usize;
        for next in chars.by_ref() {
            if next == c {
                len += 1;
            } else {
                // Put next back by re-adding iterator? Not possible.
                break;
            }
        }
        out.push(c);
        if len > 1 {
            out.push_str(&len.to_string());
        }
    }

    out
}
