fn eval_rpn(tokens: &[&str]) -> Option<i64> {
    let mut stack: Vec<i64> = Vec::new();

    for &tok in tokens {
        match tok {
            "+" | "-" | "*" | "/" => {
                if stack.len() < 2 {
                    return None;
                }
                let b = stack.pop()?;
                let a = stack.pop()?;
                let value = match tok {
                    "+" => a.checked_add(b)?,
                    "-" => a.checked_sub(b)?,
                    "*" => a.checked_mul(b)?,
                    "/" => a.checked_div(b)?,
                    _ => unreachable!(),
                };
                stack.push(value);
            }
            _ => {
                let value = tok.parse::<i64>().ok()?;
                stack.push(value);
            }
        }
    }

    if stack.len() == 1 {
        Some(stack[0])
    } else {
        None
    }
}
